f05aff6a Fix incorrect offset into fastq header in name2 mode
 sam.c | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)
commit f05aff6ac306f663b0e605f96874d56a355e1a19
Author: Rob Davies <rmd+git@sanger.ac.uk>
Date:   Tue Sep 28 12:16:49 2021 +0100

    Fix incorrect offset into fastq header in name2 mode

    The offset to skip over the first name in the fastq header
    was being applied twice, potentially causing the search for
    the comment part to fall off the end of the allocated string.

    Thanks to John Marshall for reporting this.

diff --git a/sam.c b/sam.c
index 7c82b4a7..1f02f428 100644
--- a/sam.c
+++ b/sam.c
@@ -3735,7 +3735,7 @@ static int fastq_parse1(htsFile *fp, bam1_t *b) {
     }

     l = x->name.l;
-    char *s = x->name.s + i;
+    char *s = x->name.s;
     while (i < l && !isspace_c(s[i]))
         i++;
     if (i < l) {
3944da09 Prevent endless aux_parse loop and avoid malformed aux data
 sam.c | 5 ++++-
 1 file changed, 4 insertions(+), 1 deletion(-)
commit 3944da0922f8ef489c3fa38bc44bcf40f4e73dcc
Author: Rob Davies <rmd+git@sanger.ac.uk>
Date:   Wed Apr 21 12:20:41 2021 +0100

    Prevent endless aux_parse loop and avoid malformed aux data

    In lenient mode, skip the check for integer overflows.  Fixes an
    endless loop due to `overflow` not being reset, and by the time
    the check is made all the input data has been used so trying to
    loop back won't do anything useful.

    Make the _parse_err() macro in aux_parse() reset `b->l_data` to
    where it was at the start of the loop if it detects an error in
    lenient mode.  This cleans up any semi-formed aux records that
    may be present before the parser tries to skip to the next tag.

diff --git a/sam.c b/sam.c
index b6337202..8a3f8c34 100644
--- a/sam.c
+++ b/sam.c
@@ -2405,6 +2405,7 @@ static inline unsigned int parse_sam_flag(char *v, char **rv, int *overflow) {
 static inline int aux_parse(char *start, char *end, bam1_t *b, int lenient,
                             khash_t(tag) *tag_whitelist) {
     int overflow = 0;
+    int checkpoint;
     char logbuf[40];
     char *q = start, *p = end;

@@ -2416,6 +2417,7 @@ static inline int aux_parse(char *start, char *end, bam1_t *b, int lenient,
                     q++;                        \
                 while (q < p && isspace_c(*q))    \
                     q++;                        \
+                b->l_data = checkpoint;         \
                 goto loop;                      \
             } else {                            \
                 hts_log_error(__VA_ARGS__);     \
@@ -2426,6 +2428,7 @@ static inline int aux_parse(char *start, char *end, bam1_t *b, int lenient,

     while (q < p) loop: {
         char type;
+        checkpoint = b->l_data;
         if (p - q < 5) {
             if (lenient) {
                 break;
@@ -2533,7 +2536,7 @@ static inline int aux_parse(char *start, char *end, bam1_t *b, int lenient,
         q++;
     }

-    _parse_err(overflow != 0, "numeric value out of allowed range");
+    _parse_err(!lenient && overflow != 0, "numeric value out of allowed range");
 #undef _parse_err

     return 0;
7dc751c9 Catch more errors in fastq_parse1()
 sam.c | 12 ++++++++----
 1 file changed, 8 insertions(+), 4 deletions(-)
commit 7dc751c9cdf7f7ce5a1ad324bfe4fdba102e85e8
Author: Rob Davies <rmd+git@sanger.ac.uk>
Date:   Fri Apr 16 17:27:35 2021 +0100

    Catch more errors in fastq_parse1()

    Also fixes a couple of places where errors could be
    incorrectly reported as EOF.

diff --git a/sam.c b/sam.c
index fbf83378..b6337202 100644
--- a/sam.c
+++ b/sam.c
@@ -3710,7 +3710,8 @@ static int fastq_parse1(htsFile *fp, bam1_t *b) {
         if (*fp->line.s == (fp->format.format == fastq_format ? '+' : '>')
             || ret == -1)
             break;
-        kputsn(fp->line.s, fp->line.l, &x->seq);
+        if (kputsn(fp->line.s, fp->line.l, &x->seq) < 0)
+            return -2;
     }

     // Qual
@@ -3720,7 +3721,10 @@ static int fastq_parse1(htsFile *fp, bam1_t *b) {
         do {
             if (hts_getline(fp, KS_SEP_LINE, &fp->line) < 0)
                 return -2;
-            kputsn(fp->line.s, fp->line.l, &x->qual);
+            if (fp->line.l > remainder)
+                return -2;
+            if (kputsn(fp->line.s, fp->line.l, &x->qual) < 0)
+                return -2;
             remainder -= fp->line.l;
         } while (remainder > 0);

@@ -3787,14 +3791,14 @@ static int fastq_parse1(htsFile *fp, bam1_t *b) {

     if (ret >= 0 && barcode_len)
         if (bam_aux_append(b, x->BC, 'Z', barcode_len, (uint8_t *)barcode) < 0)
-            ret = -1;
+            ret = -2;

     if (!x->aux)
         return ret;

     // Identify any SAM style aux tags in comments too.
     if (aux_parse(&kc->s[barcode_len], kc->s + kc->l, b, 1, x->tags) < 0)
-        ret = -1;
+        ret = -2;

     return ret;
 }
